//! Exact original selected CODE_MAPS UI facts and full judgment over current original loans.
//! Retained lexical facts are DATA, never source, semantic model or EOF authority.
use crate::{captured_api_pages as fund,captured_generator_budget::Budget,captured_raw_file::Config,captured_reactive_reads::Failure,captured_allow_annotations::PatternOperation,reactive_raw_policy_pages::RawPolicyPages};
use std::{io,sync::Arc};
pub fn metadata()->&'static crate::lint::Meta{static M:std::sync::OnceLock<crate::lint::Meta>=std::sync::OnceLock::new();M.get_or_init(||crate::dm::sys::module_metadata(&crate::dm::sys::SysModule{name:crate::allow_registry_fields::sys_ui::SCOPE_MODULE_NAME,rules:crate::allow_registry_fields::sys_ui::RULES,..crate::dm::sys::SysModule::DEFAULT},crate::lint::ScanKind::Tree))}
struct Fact{relative:String,data:crate::sys_ui_policy::Facts}
struct Phase{budget:Arc<Budget>,complete:bool}impl Drop for Phase{fn drop(&mut self){if !self.complete{self.budget.keep_failed_scratch()}}}
fn oom(b:&Budget)->Failure{b.deny();Failure::Operational(io::ErrorKind::OutOfMemory.into())}
fn selected(config:&Config,relative:&str)->bool{!config.policy_path_exempt("sys/ui","sys",relative)}
pub fn collect(pages:&dyn RawPolicyPages,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>)->Result<fund::ApiData,Failure>{collect_using(pages,config,root,poll,None)}
#[cfg(feature="native-policy")]
pub fn collect_with_patterns(pages:&dyn RawPolicyPages,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,patterns:&dyn crate::native_pattern::Provider)->Result<fund::ApiData,Failure>{collect_using(pages,config,root,poll,Some(patterns))}
fn collect_using(pages:&dyn RawPolicyPages,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,patterns:Option<&dyn crate::native_pattern::Provider>)->Result<fund::ApiData,Failure>{fund::checked(root,poll)?;let mut phase=Phase{budget:Budget::scoped_temporaries(root).map_err(|_|oom(root))?,complete:false};let b=&phase.budget;let pending=(||{
 let mut facts=Vec::new();if !pages.for_each(&mut|relative,views|{fund::checked(b,poll)?;if !selected(config,relative){return Ok(true)}let file=views.source_file()?;if relative!=file.rel{return Err("UI original facts path differs".into())}let local=views.allocation_budget(root);let mut keep=PatternOperation{patterns,budget:b,poll};let mut temporary=PatternOperation{patterns,budget:local,poll};let data=crate::sys_ui_policy::facts_using(file,&mut keep,&mut temporary)?;fund::row(b,poll,&mut facts)?;facts.push(Fact{relative:fund::own(b,poll,relative)?,data});fund::checked(local,poll)?;Ok(true)})?{return Err("UI complete original facts stopped before EOF".into())}
 b.charge(facts.len().checked_mul(4*std::mem::size_of::<Fact>()).and_then(|n|n.checked_add(128)).ok_or_else(||oom(b))?).map_err(|_|oom(b))?;facts.sort_by(|a,b|a.relative.cmp(&b.relative));let mut refs=Vec::new();fund::reserve_append(b,poll,&mut refs,facts.len())?;for f in &facts{refs.push(&f.data);}let mut keep=PatternOperation{patterns,budget:b,poll};let mut temporary=PatternOperation{patterns,budget:b,poll};let context=crate::sys_ui_policy::context_using(&refs,&mut keep,&mut temporary)?;
 let mut batches=Vec::new();if !pages.for_each(&mut|relative,views|{fund::checked(b,poll)?;if !selected(config,relative){return Ok(true)}let file=views.source_file()?;if file.rel!=relative{return Err("UI original judgment path differs".into())}let local=views.allocation_budget(root);let mut keep=PatternOperation{patterns,budget:b,poll};let mut temporary=PatternOperation{patterns,budget:local,poll};let rows=crate::sys_ui_policy::judge_using(file,&context,&mut keep,&mut temporary)?;let data=crate::captured_sys_fields_pages::record_rows_with_patterns(views,rows,&[],&[],root,poll,patterns)?;fund::row(b,poll,&mut batches)?;batches.push((fund::own(b,poll,relative)?,data));Ok(true)})?{return Err("UI complete original judgment stopped before EOF".into())}
 b.charge(batches.len().checked_mul(4*std::mem::size_of::<(String,fund::ApiData)>()).and_then(|n|n.checked_add(128)).ok_or_else(||oom(b))?).map_err(|_|oom(b))?;batches.sort_by(|a,b|a.0.cmp(&b.0));let mut data=fund::empty();for(_,batch)in batches{fund::append(&mut data,batch,root,poll)?;}fund::checked(b,poll)?;Ok(data)
})();if matches!(&pending,Err(Failure::Operational(_))){return pending}fund::checked(root,poll)?;phase.complete=pending.is_ok();drop(phase);pending}
